import java.util.*;

class Solution {
    public List<String> rebuildAddresses(String s) {
        List<String> out = new ArrayList<>();
        go(s, 0, new ArrayList<String>(), out);
        return out;
    }

    private void go(String s, int pos, List<String> parts, List<String> out) {
        int left = s.length() - pos, need = 4 - parts.size();
        if (need == 0) {
            if (left == 0) out.add(String.join(".", parts));
            return;
        }
        if (left < need || left > 3 * need) return;     // can't fit the remaining parts
        for (int len = 1; len <= 3 && pos + len <= s.length(); len++) {
            String piece = s.substring(pos, pos + len);
            if (len > 1 && piece.charAt(0) == '0') break; // leading zero not allowed
            if (Integer.parseInt(piece) > 255) break;     // longer pieces are even bigger
            parts.add(piece);
            go(s, pos + len, parts, out);
            parts.remove(parts.size() - 1);
        }
    }
}

