class Solution:
    def rebuildAddresses(self, s: str) -> List[str]:
        out = []
        def go(i, parts):
            if len(parts) == 4:
                if i == len(s): out.append(".".join(parts))
                return
            for L in range(1, 4):
                p = s[i:i + L]
                if len(p) < L: break
                if (len(p) > 1 and p[0] == "0") or int(p) > 255: continue
                go(i + L, parts + [p])
        go(0, [])
        return out

