function rebuildAddresses(s) {
  const out = [], n = s.length;
  const ok = p => p.length > 0 && p.length <= 3 && !(p.length > 1 && p[0] === "0") && Number(p) <= 255;
  for (let a = 1; a <= 3; a++) for (let b = 1; b <= 3; b++) for (let c = 1; c <= 3; c++) {
    const d = n - a - b - c; if (d < 1 || d > 3) continue;
    const ps = [s.slice(0, a), s.slice(a, a + b), s.slice(a + b, a + b + c), s.slice(a + b + c)];
    if (ps.every(ok)) out.push(ps.join("."));
  }
  return out;
}
